<!DOCTYPE html>
<html>
<head>
    <title>Certificate of Completion</title>
    <style>
        body { 
            font-family: serif; 
            margin: 40px; 
            text-align: center;
            background: linear-gradient(45deg, #f0f8ff, #e6f3ff);
        }
        .certificate {
            border: 8px double #2c5aa0;
            padding: 40px;
            background: white;
            max-width: 800px;
            margin: 0 auto;
            box-shadow: 0 0 20px rgba(0,0,0,0.1);
        }
        .header { font-size: 36px; color: #2c5aa0; margin-bottom: 20px; }
        .subtitle { font-size: 18px; color: #666; margin-bottom: 30px; }
        .student { font-size: 28px; font-weight: bold; color: #333; margin: 20px 0; }
        .course { font-size: 22px; color: #2c5aa0; margin: 20px 0; }
        .date { font-size: 16px; margin: 30px 0 10px 0; }
        .number { font-size: 12px; color: #888; position: absolute; bottom: 20px; right: 20px; }
    </style>
</head>
<body>
    <div class="certificate">
        <div class="header">Certificate of Completion</div>
        <div class="subtitle">This certifies that</div>
        <div class="student">${studentName}</div>
        <div class="subtitle">has successfully completed the course</div>
        <div class="course">${courseName}</div>
        <div class="date">Date of Completion: ${issuedDate}</div>
        <div class="number">Certificate #: ${certificateNumber}</div>
    </div>
</body>
</html>
