          to { opacity: 1; transform: translateY(0); }
        }

        .certificates-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
          gap: 24px;
          margin-top: 20px;
        }

        .certificate-card {
          background: white;
          border: 2px solid #e2e8f0;
          border-radius: 16px;
          padding: 24px;
          position: relative;
          transition: all 0.3s ease;
          box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
        }

        .certificate-card:hover {
          transform: translateY(-4px);
          box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1);
          border-color: #667eea;
        }

        .certificate-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 20px;
          padding-bottom: 15px;
          border-bottom: 2px solid #f7fafc;
        }

        .certificate-icon {
          font-size: 2.5rem;
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          background-clip: text;
        }

        .certificate-number {
          font-size: 0.9rem;
          color: #718096;
          font-weight: 600;
          background: #f7fafc;
          padding: 4px 12px;
          border-radius: 20px;
          border: 1px solid #e2e8f0;
        }

        .certificate-content {
          margin-bottom: 24px;
        }

        .certificate-course {
          font-size: 1.25rem;
          font-weight: 600;
          color: #2d3748;
          margin: 0 0 16px 0;
          line-height: 1.4;
        }

        .certificate-details {
          display: flex;
          flex-direction: column;
          gap: 8px;
        }

        .detail-item {
          display: flex;
          justify-content: space-between;
          align-items: center;
        }

        .detail-label {
          font-size: 0.9rem;
          color: #718096;
          font-weight: 500;
        }

        .detail-value {
          font-size: 0.9rem;
          color: #2d3748;
          font-weight: 600;
        }

        .detail-value.grade {
          color: #667eea;
          background: #ebf4ff;
          padding: 2px 8px;
          border-radius: 12px;
          font-size: 0.85rem;
        }

        .certificate-actions {
          display: flex;
          justify-content: center;
        }

        .download-btn {
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          border: none;
          padding: 12px 24px;
          border-radius: 8px;
          font-weight: 600;
          cursor: pointer;
          transition: all 0.2s;
          display: flex;
          align-items: center;
          gap: 8px;
          font-size: 0.9rem;
          width: 100%;
          justify-content: center;
        }

        .download-btn:hover:not(:disabled) {
          transform: translateY(-1px);
          box-shadow: 0 4px 12px rgba(102, 126, 234, 0.4);
        }

        .download-btn:disabled {
          opacity: 0.7;
          cursor: not-allowed;
        }

        .loading-spinner {
          width: 16px;
          height: 16px;
          border: 2px solid rgba(255, 255, 255, 0.3);
          border-top: 2px solid white;
          border-radius: 50%;
          animation: spin 1s linear infinite;
        }

        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }

        @media (max-width: 768px) {
          .certificates-grid {
            grid-template-columns: 1fr;
            gap: 20px;
          }

          .certificate-card {
            padding: 20px;
          }

          .certificate-course {
            font-size: 1.1rem;
          }
        }
